// generator-of-generators sketch for: Workflow Compiler Generator
function makeGenerator(task) {
  const g = { name: task + '-gen', version: '0.1.0',
    artifacts: { schema: task + '.schema.json', logic: task + '.logic.js', tests: task + '.tests.js' },
    validate: function(a) { return ['schema','logic','tests'].every(k => typeof a[k] === 'string'); } };
  return g;
}
const g = makeGenerator('Workflow_Compiler_Generator');
const ok = g.validate(g.artifacts);
console.log(JSON.stringify({ generator: g.name, artifacts: Object.keys(g.artifacts),
  selfValid: ok, families: 4 }));

